CREATE OR REPLACE FUNCTION soi_security.has_role(allowed_roles text[]) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$ SELECT EXISTS (SELECT 1 FROM public.profiles p WHERE p.id = auth.uid() AND p.estado = 'activo' AND p.activo IS TRUE AND p.rol = ANY(allowed_roles)); $$; REVOKE ALL ON FUNCTION soi_security.has_role(text[]) FROM PUBLIC, anon; GRANT EXECUTE ON FUNCTION soi_security.has_role(text[]) TO authenticated;